    $('#publish-content').innerHTML=`<p class="muted">${esc(p.nickname)} · ${esc(p.city)} · ${esc(purposeText(p))}</p><p class="muted">${esc(p.bio)}</p><dl class="detail-dl">${Object.entries(publicCard.fields).map(([key,value])=>`<div><dt>${esc(fieldLabels[key]||key)}</dt><dd>${esc(shownValue(key,value))}</dd></div>`).join('')}${publicCard.chart.dayMaster?`<div><dt>日主</dt><dd>${esc(publicCard.chart.dayMaster)}</dd></div>`:''}${publicCard.chart.zodiac?`<div><dt>生肖</dt><dd>${esc(publicCard.chart.zodiac)}</dd></div>`:''}${['constellation','mbti'].filter(k=>publicCard[k]).map(k=>`<div><dt>${typeLabels[k]}</dt><dd>${esc(publicCard[k])}</dd></div>`).join('')}</dl><div class="tags">${(p.hobbies||[]).map(hobby=>`<span>${esc(hobby)}</span>`).join('')}</div><p class="fine-print">互相认识后：${connected.map(key=>fieldLabels[key]||{dayMaster:'日主',zodiac:'生肖',...typeLabels}[key]).map(esc).join('、')||'无'}。<br>仅自己可见：${privateFields.map(key=>fieldLabels[key]||{dayMaster:'日主',zodiac:'生肖',...typeLabels}[key]).map(esc).join('、')||'无'}。</p><p class="fine-print">生日与出生城市不公开。联系方式${data.contactConsent?'仅在双方都同意认识和分享时解锁':'未授权分享'}。收入资产是个人自报，不代表认证。</p>`;
    const needsPolicy=data.policyVersion!==POLICY_VERSION;if(needsPolicy)$('#publish-content').insertAdjacentHTML('beforeend','<label class="check-line"><input id="publish-policy" type="checkbox" required>我同意<a href="/pages/friends-privacy.html" target="_blank" rel="noopener">隐私说明</a>中交友资料处理方式，并接受<a href="/pages/friends-terms.html" target="_blank" rel="noopener">服务条款</a>。</label>');const dialog=$('#publish-dialog');dialog.returnValue='cancel';event('profile_preview');dialog.showModal();return new Promise(resolve=>dialog.addEventListener('close',()=>{const accepted=dialog.returnValue==='publish';if(accepted&&needsPolicy)data.policyVersion=POLICY_VERSION;resolve(accepted);},{once:true}));
