    const dirs=(c.directions||[]).map(d=>`<article class="direction"><strong>${esc(d.label)} · ${esc((d.stems||[]).join(' / '))}${esc(d.element||'')}</strong><p><b>对方对我：</b>${esc(d.forMe||d.relation||'从五行关系开始了解')}</p><p><b>我对对方：</b>${esc(d.forThem||'彼此的实际感受，需要在相处中了解。')}</p></article>`).join('');
