  function privateZodiacReason(zodiac){
    const pair=['鼠牛','虎猪','兔狗','龙鸡','蛇猴','马羊'].find(g=>g.includes(zodiac)),group=['猴鼠龙','猪兔羊','虎马狗','蛇鸡牛'].find(g=>g.includes(zodiac));
    if(!zodiac||!pair||!group)return '';
    const partner=[...pair].filter(x=>x!==zodiac).join('、'),others=[...group].filter(x=>x!==zodiac).join('、');
    return `<section class="surface private-zodiac-reason"><h2>为什么推荐这些生肖？</h2><p class="fine-print">仅自己可见 · 不进入分享图片或对方的资料页</p><p><strong>六合：${esc(partner)}</strong>。传统地支将十二生肖分为六组两两相合，你的生肖与${esc(partner)}属于其中一组。</p><p><strong>三合参考：${esc(others)}</strong>。${esc([...group].join('、'))}在传统地支中属于同一三合组，因此把另外两个生肖列作认识方向；两个人不等于组成完整三合局。</p><p class="fine-print">这是文化偏好参考，不保证相处结果。自己的生肖是否公开，可在资料与分享设置里选择。</p></section>`;
  }
