    button.disabled=true;$('#profile-error').textContent='';if(data.listed&&!await publicationPreview(data)){button.disabled=false;return;}try{const r=await post('/api/friends/profile',data);state.profile=r.profile;state.chart=r.profile.chart;state.credential=null;state.intakeDraft=null;state.guestProfileDraft=null;updateAccount();toast(data.purposes.includes('serious')?'资料已保存。可以在我的卡片继续填写婚恋10个方向。':'交友卡已保存。海报将只包含公开资料。');location.hash='poster';}catch(err){if($('#profile-error'))$('#profile-error').textContent=err.message;else toast(err.message);}finally{button.disabled=false;}
