  function availabilityEditor(value){
    const deviceZone=Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Shanghai',zone=value?.timeZone||deviceZone;
    const zones=[...new Set([zone,deviceZone,'Asia/Shanghai','Asia/Hong_Kong','Asia/Tokyo','Asia/Singapore','Asia/Seoul','Asia/Kolkata','Australia/Sydney','Europe/London','Europe/Paris','Europe/Berlin','America/New_York','America/Chicago','America/Denver','America/Los_Angeles','America/Toronto','Pacific/Auckland'])];
    return `<details class="availability-editor"><summary>每周可约时间 <span>选填</span></summary><p class="fine-print">每周重复，只向本人和已互相认识的人提供。可随时暂停，不会出现在海报或公开卡片。</p><div class="availability-settings"><label>时间按<select id="availability-zone">${zones.map(item=>`<option value="${esc(item)}" ${item===zone?'selected':''}>${esc(zoneLabel(item))}</option>`).join('')}</select></label><label class="check-line"><input type="checkbox" id="availability-paused" ${value?.paused?'checked':''}>暂停可约时间</label></div><div id="availability-slots">${(value?.slots||[]).map(availabilityRow).join('')}</div><button type="button" class="text-button" id="add-availability">＋ 添加时间段</button><p class="fine-print">默认采用设备时区，与你的出生城市无关。按当地时间填写；跨午夜请拆成两天。</p></details>`;
  }
  function residenceEditor(value){return `<details class="residence-editor"><summary>常住附近 <span>选填</span></summary><p class="fine-print">只需商圈、地铁站或小区，不填门牌。原始位置仅自己与平台使用，用于双方见面地点建议。</p><label class="check-line"><input type="checkbox" id="residence-consent" ${value?.consent?'checked':''}>我同意后台将这个大致位置用于双方见面地点建议。</label><div class="residence-search"><label for="residence-query">附近区域</label><input id="residence-query" type="search" autocomplete="off" placeholder="搜索公共区域，如 望京" value="${esc(value?.label||'')}" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="residence-results"><div id="residence-results" class="city-results" role="listbox" hidden></div></div><p id="residence-status" class="city-selection">${value?'已确认：'+esc(value.label)+'（商圈级）':''}</p><div class="compact-actions"><button type="button" class="secondary" id="locate-residence">使用我附近的位置</button><button type="button" class="text-button" id="remove-residence">${value?'删除已存位置':'清空位置'}</button></div><p class="fine-print">设备定位只取一次，保存到约 1 公里精度；请在你希望作为出发区域的地方使用。</p><p id="residence-error" class="error" role="alert"></p></details>`;}
  function bindResidenceEditor(value){
    const query=$('#residence-query'),results=$('#residence-results'),consent=$('#residence-consent'),status=$('#residence-status');let draft=value?{...value}:null,sequence=0,timer;
    function clearDraft(){draft=null;query.value='';status.textContent='';results.hidden=true;query.setAttribute('aria-expanded','false');$('#residence-error').textContent='';}
    function setDraft(next){draft={label:String(next.label).slice(0,100),lat:Math.round(Number(next.lat)*100)/100,lng:Math.round(Number(next.lng)*100)/100,source:next.source,consent:true};query.value=draft.label;status.textContent='已确认：'+draft.label+'（商圈级）';results.hidden=true;query.setAttribute('aria-expanded','false');$('#residence-error').textContent='';}
    query.addEventListener('input',()=>{draft=null;status.textContent='文字尚未确认位置，请选择搜索结果。';clearTimeout(timer);const text=query.value.trim(),current=++sequence;if(!text){status.textContent='';results.hidden=true;return;}timer=setTimeout(async()=>{try{const response=await api('/api/friends/areas?q='+encodeURIComponent(text));if(current!==sequence||!results.isConnected)return;results.hidden=false;query.setAttribute('aria-expanded','true');const areas=response.areas||[];results.innerHTML=areas.length?areas.map((area,index)=>`<button type="button" class="city-result" role="option" data-area-index="${index}">${esc(area.label)}<small>${esc(area.city||'公共区域')}</small></button>`).join(''):'<p class="city-message">暂未收录这个区域，可改用设备定位或跳过。</p>';results.querySelectorAll('[data-area-index]').forEach(button=>button.addEventListener('click',()=>{if(!consent.checked){$('#residence-error').textContent='请先同意将大致位置用于见面建议。';return;}setDraft({...areas[Number(button.dataset.areaIndex)],source:'area'});}));}catch(error){$('#residence-error').textContent=error.message;}},250);});
    query.addEventListener('keydown',pressed=>{if(pressed.key==='ArrowDown'&&!results.hidden){pressed.preventDefault();results.querySelector('button')?.focus();}else if(pressed.key==='Escape'){results.hidden=true;query.setAttribute('aria-expanded','false');}});
    results.addEventListener('keydown',pressed=>{const options=[...results.querySelectorAll('button')],index=options.indexOf(document.activeElement);if(pressed.key==='ArrowDown'||pressed.key==='ArrowUp'){pressed.preventDefault();options[(index+(pressed.key==='ArrowDown'?1:-1)+options.length)%options.length]?.focus();}else if(pressed.key==='Escape'){results.hidden=true;query.focus();}});
    $('#locate-residence').addEventListener('click',()=>{if(!consent.checked){$('#residence-error').textContent='请先同意将大致位置用于见面建议。';return;}if(!navigator.geolocation){$('#residence-error').textContent='当前浏览器不支持定位，可改选公共区域。';return;}const button=$('#locate-residence');button.disabled=true;$('#residence-error').textContent='';navigator.geolocation.getCurrentPosition(position=>{button.disabled=false;if(!consent.isConnected||!consent.checked)return;setDraft({label:query.value.trim()||'当前位置附近',lat:position.coords.latitude,lng:position.coords.longitude,source:'device'});},error=>{button.disabled=false;if($('#residence-error'))$('#residence-error').textContent=error.code===1?'未获得定位权限，可以改选公共区域。':'暂时无法定位，请重试或改选公共区域。';},{enableHighAccuracy:false,timeout:10000,maximumAge:0});});
    $('#remove-residence').addEventListener('click',async()=>{sequence++;clearTimeout(timer);if(!state.profile?.residence){clearDraft();return;}if(!confirm('确认从后台删除已保存的位置？交友档案仍保留。'))return;const data=profilePayload(state.profile);data.residence=null;try{const result=await post('/api/friends/profile',data);state.profile=result.profile;clearDraft();$('#remove-residence').textContent='清空位置';toast('后台保存的位置已删除。');}catch(error){$('#residence-error').textContent=error.message;}});
    consent.addEventListener('change',()=>{if(!consent.checked){draft=null;status.textContent='已撤回本次位置授权；保存资料后删除已存位置，也可直接点击删除。';}});
    readResidenceDraft=()=>{if(!consent.checked)return null;if(!draft&&query.value.trim())throw Error('常住附近尚未确认：请选择公共区域、使用定位，或清空后跳过。');return draft?{...draft,consent:true}:null;};
  }
  function planEditor(shareId){return `<details class="connection-plan"><summary>看看共同空档与见面建议</summary><div class="plan-controls"><label>这次想约<select data-plan-duration><option value="15">15 分钟通话</option><option value="60">60 分钟见面</option></select></label><button type="button" class="secondary" data-plan-share="${esc(shareId||'')}">查看建议</button></div><div class="plan-results" aria-live="polite"></div></details>`;}
  function bindPlanEditors(root){root.querySelectorAll('[data-plan-share]').forEach(button=>button.addEventListener('click',async()=>{const section=button.closest('.connection-plan'),output=section.querySelector('.plan-results');button.disabled=true;output.textContent='正在寻找双方可用的时间与公共地点…';try{const result=await post('/api/friends/plan',{shareId:button.dataset.planShare,durationMinutes:Number(section.querySelector('[data-plan-duration]').value)}),slots=result.commonSlots||result.slots||[],places=result.places||[];output.innerHTML='<h4>共同空档</h4>'+(slots.length?slots.slice(0,8).map(slot=>`<p class="plan-slot">你：${esc(slot.localLabel?.a||slot.start)}<br>对方：${esc(slot.localLabel?.b||slot.start)}</p>`).join(''):'<p class="fine-print">暂未找到共同空档，可以先更新自己的每周可约时间。</p>')+'<h4>公共地点参考</h4>'+(places.length?places.slice(0,8).map(place=>`<article class="plan-place"><strong>${esc(place.name)}</strong><p>${esc([place.category,...(place.activities||[])].filter(Boolean).join(' · '))}</p>${place.note?`<p>${esc(place.note)}</p>`:''}${safeSourceUrl(place.sourceUrl)?`<a class="text-button" href="${esc(safeSourceUrl(place.sourceUrl))}" target="_blank" rel="noopener noreferrer">查看地点来源 ↗</a>`:''}</article>`).join(''):`<p class="fine-print">${result.locationReady?'这个区域暂无收录的地点，可以自行商量公共场所。':'双方可自愿确认大致位置后，再尝试地点建议。'}</p>`)+`<p class="fine-print">${esc(result.note||'仅为候选建议，尚未邀约或预订。')}</p><a class="text-button" href="#profile">修改我的可约时间与大致位置</a>`;}catch(error){output.innerHTML='<p class="error">'+esc(error.message)+'</p>';}finally{button.disabled=false;}}));}
  function safeSourceUrl(value){try{const url=new URL(String(value));return url.protocol==='https:'?url.href:'';}catch{return '';}}
  function zoneLabel(zone){return (({'Asia/Shanghai':'北京 / 上海','Asia/Hong_Kong':'香港','Asia/Tokyo':'东京','Asia/Singapore':'新加坡','Asia/Seoul':'首尔','Asia/Kolkata':'印度','Australia/Sydney':'悉尼','Europe/London':'伦敦','Europe/Paris':'巴黎','Europe/Berlin':'柏林','America/New_York':'纽约','America/Chicago':'芝加哥','America/Denver':'丹佛','America/Los_Angeles':'洛杉矶','America/Toronto':'多伦多','Pacific/Auckland':'奥克兰'})[zone]||zone.split('/').pop().replace(/_/g,' '))+' · '+zone;}
  function availabilityRow(slot={weekday:6,start:'14:00',end:'18:00'}){return `<div class="availability-slot"><label>每周<select data-slot-weekday aria-label="每周星期">${['一','二','三','四','五','六','日'].map((day,index)=>`<option value="${index+1}" ${Number(slot.weekday)===index+1?'selected':''}>周${day}</option>`).join('')}</select></label><label>开始<input data-slot-start type="text" inputmode="numeric" value="${esc(slot.start)}" maxlength="12" placeholder="14:00" aria-label="开始时间"></label><label>结束<input data-slot-end type="text" inputmode="numeric" value="${esc(slot.end)}" maxlength="12" placeholder="18:00" aria-label="结束时间"></label><button type="button" class="text-button" data-remove-slot>删除</button></div>`;}
  function bindAvailabilityEditor(){
    const rows=$('#availability-slots');rows.addEventListener('click',clicked=>{const remove=clicked.target.closest('[data-remove-slot]');if(remove)remove.closest('.availability-slot').remove();});
    $('#add-availability').addEventListener('click',()=>{if(rows.children.length>=14){toast('最多设置 14 个每周时间段。');return;}rows.insertAdjacentHTML('beforeend',availabilityRow());});
    rows.addEventListener('focusout',blurred=>{if(!blurred.target.matches('[data-slot-start],[data-slot-end]'))return;try{blurred.target.value=normalizeBirthTime(blurred.target.value);}catch{}});
  }
  function readAvailability(){
    const rows=[...document.querySelectorAll('.availability-slot')];if(!rows.length)return null;
    const slots=rows.map((row,index)=>{let start,end;try{start=normalizeBirthTime(row.querySelector('[data-slot-start]').value);end=normalizeBirthTime(row.querySelector('[data-slot-end]').value);}catch{throw Error(`请核对第 ${index+1} 个可约时间段的小时和分钟。`);}if(end<=start)throw Error('可约时间的结束需晚于开始；跨午夜请拆成两天。');return {weekday:Number(row.querySelector('[data-slot-weekday]').value),start,end};});
    return {paused:$('#availability-paused').checked,timeZone:$('#availability-zone').value,slots};
  }
  function fiveElementGuide(p, own) {
    const names=[...'甲乙丙丁戊己庚辛壬癸'],elements=[...'木火土金水'];
    const a=names.indexOf(own?.chart?.dayMaster),b=names.indexOf(p.chart?.dayMaster);
    const common=(p.hobbies||[]).filter(h=>(own?.hobbies||[]).includes(h)).slice(0,2);
    let basis='',question='';
    if(a>=0&&b>=0){
      const x=Math.floor(a/2),y=Math.floor(b/2);
      if((y+1)%5===x){basis='传统五行里，'+elements[y]+'生'+elements[x]+'，可作为探索支持与回应的认识方向。';question='你遇到困难时，希望我倾听、鼓励，还是一起想办法？';}
      else if((x+1)%5===y){basis='传统五行里，'+elements[x]+'生'+elements[y]+'，你也可以从主动支持对方开始建立连接。';question='我们各自希望得到什么支持，又愿意为彼此做些什么？';}
      else if(x===y){basis='你们的日主同属'+elements[x]+'，可以从共同话题开始了解各自的不同。';question='同样面对压力，我们分别习惯怎样放松？';}
      else {basis='你们的日主五行不同，可以先了解彼此的节奏与边界；单凭日主不能判断是否适合。';question='遇到意见不同时，你希望我们怎样沟通？';}
    }
    return {basis,question,common};
  }
  function fiveElementGuideHTML(p,compact=false){
    const own=state.profile||(state.chart?{chart:state.chart,hobbies:[]}:null);
    if(!own)return '';
    const g=fiveElementGuide(p,own);
    if(!g.basis&&!g.common.length)return '';
    return '<section class="five-element-guide" aria-label="五行找人推荐说明"><h3>你们可以从这里开始</h3>'+
      (g.basis?'<p>'+esc(g.basis)+'</p>':'')+
      (g.common.length?'<p><strong>实际连接点：</strong>你们都填写了'+g.common.map(esc).join('、')+'。</p>':'')+
      (!compact&&g.question?'<p><strong>第一次聊：</strong>'+esc(g.question)+'</p>':'')+
      (!compact?'<p class="fine-print">五行是文化认识线索。彼此能带来什么，要通过真实沟通确认；不代表完整合盘结论。</p>':'')+'</section>';
  }
  function cardHTML(p){const c=p.chart||{},f=p.fields||{};return `<article class="person-card"><div class="person-top"><div class="person-stem">${esc(c.dayMaster||'缘')}</div><span class="pill">${esc(purposeText(p))}</span></div><div class="person-body"><h2>${esc(p.nickname)}</h2><div class="muted">${esc(p.city)}${f.age?' · '+esc(f.age)+' 岁'+(p.ageAsOf?'（截至 '+esc(p.ageAsOf)+'）':''):''}${c.zodiac?' · 属'+esc(c.zodiac):''}</div><p class="intro">${esc(p.bio||'想从一个简单的招呼开始认识。')}</p><div class="tags">${[...Object.entries(f).filter(([k])=>k!=='age').slice(0,3).map(([k,val])=>`${fields[k]?.split(' / ')[0]||k} ${shownValue(k,val)}`),...(p.hobbies||[]).slice(0,1)].map(v=>`<span>${esc(v)}</span>`).join('')}</div><div class="tags">${visibleTypeTags(p)}</div>${(p.reasons||[]).length?`<p class="fine-print">推荐依据：${p.reasons.map(esc).join('；')}</p>`:''}${explanationHTML(p)}${fiveElementGuideHTML(p,true)}<button class="secondary" data-detail="${esc(p.shareId)}">看看交友卡 ↗</button></div></article>`;}
  async function showDiscover(){
    setView(`<section class="page-wrap">${heading('PEOPLE YOU MAY WANT TO MEET','想认识的人，也在寻找同路人。','从五行、生肖、星座和MBTI认识朋友。只展示本人允许被看到的资料。')}<form id="filter-form" class="filter-bar"><label>城市<input name="city" value="${esc(state.profile?.city||'')}" maxlength="20" placeholder="所有城市"></label><label>日主<select name="stem"><option value="">不限日主</option>${stems.map(s=>`<option>${s}</option>`).join('')}</select></label><label>生肖<select name="zodiac"><option value="">不限生肖</option>${zodiacs.map(s=>`<option>${s}</option>`).join('')}</select></label><label>星座<select name="constellation"><option value="">不限星座</option>${constellations.map(s=>`<option>${s}</option>`).join('')}</select></label><label>MBTI<select name="mbti"><option value="">不限MBTI</option>${mbtiTypes.map(s=>`<option>${s}</option>`).join('')}</select></label><button class="secondary" type="submit">寻找新朋友 ↗</button></form><div id="discover-results" class="loading">正在寻找真实的交友卡…</div></section>`);
    $('#filter-form').addEventListener('submit',e=>{e.preventDefault();loadPeople();});await loadPeople();
  }
  async function loadPeople(){const target=$('#discover-results');if(!target)return; if(!state.user){target.className='';target.innerHTML=empty('先登录，才能发现新朋友。','你可以先免费查日主，再创建自己的交友卡。人库只展示愿意被发现的真实资料。','登录 / 注册','#login');return;}if(!state.profile){target.className='';target.innerHTML=empty('先介绍自己，再认识新朋友。','完整建立自己的交友卡，是加入这场相遇的第一步。','完善我的资料','#profile');return;}target.className='loading';target.textContent='正在寻找真实的交友卡…';try {const f=new FormData($('#filter-form'));const data=await api('/api/friends/discover?'+new URLSearchParams(f).toString());if(!target.isConnected)return;target.className=data.profiles?.length?'people-grid':'';target.innerHTML=data.profiles?.length?data.profiles.map(cardHTML).join(''):empty('这次还没有找到符合条件的人。','可以放宽日主或生肖偏好，也可以分享自己的卡片，让愿意认识你的人来到这里。','分享我的卡片','#poster');bindDetails(target);}catch(e){target.className='';target.innerHTML=empty('暂时未能读取交友卡。',esc(e.message),'完善我的资料','#profile');}}
  function dateActivityOptions(p){
    const mine=state.profile?.hobbies||[],theirs=p.hobbies||[];
    if(!mine.length||!theirs.length)return '<p class="fine-print">双方补充爱好后，这里会推荐 3～5 个一起想做的活动。</p>';
    const catalog=[['羽毛球轻松对打',['羽毛球','运动','健身'],'先热身，不计分也可以'],['双人陶艺',['陶艺','手工','艺术'],'各做一个杯子，交换创意'],['合作烘焙',['烘焙','美食','做饭'],'一起完成一份甜点'],['逛展互拍',['展览','摄影','艺术'],'各选一件喜欢的作品聊聊'],['保龄球小挑战',['保龄球','运动','健身'],'轻松打几局，新手也能试'],['植物园散步',['徒步','植物','摄影','户外'],'边走边聊，按彼此节奏'],['合作桌游',['桌游','游戏'],'选规则简单的合作游戏'],['书店寻宝',['看书','阅读','书店'],'互相挑一本想推荐的书'],['手工皮具',['手工皮具','手工','设计'],'一起做卡套或钥匙扣'],['乒乓球体验',['乒乓球','运动'],'先练接球，慢慢找到节奏'],['匹克球体验',['匹克球','网球','运动'],'一起学一项双人运动']];
    const matches=(hobbies,tags)=>hobbies.some(h=>tags.some(t=>h.includes(t)));
    const choices=catalog.map(([name,tags,detail])=>{const a=matches(mine,tags),b=matches(theirs,tags);return {name,detail,score:a&&b?3:a||b?1:0,reason:a&&b?'来自双方的爱好':a?'来自你的爱好，邀请对方试试':b?'来自对方的爱好，你也可以试试':'换一种新体验'};}).sort((a,b)=>b.score-a.score).slice(0,4);
    return `<section class="surface"><h3>约会想一起做什么？</h3><p class="muted">根据双方爱好，先选一个想尝试的活动。</p>${choices.map(c=>`<label class="check-line"><input type="checkbox" name="date-activity" value="${esc(c.name)}"><span><strong>${esc(c.name)}</strong><br>${esc(c.detail)}<br><small>${esc(c.reason)}</small></span></label>`).join('')}<p class="fine-print">勾选仅供当前页面挑选，不会发送给对方。选好后可以在聊天中商量；地点和预约由双方自行安排。</p></section>`;
  }
  function bindDetails(root){root.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',()=>showDetail(b.dataset.detail)));}
